package com.jobsphere.controller;
import com.jobsphere.entity.User; import com.jobsphere.repository.UserRepository; import com.jobsphere.service.TokenService; import org.springframework.web.bind.annotation.RequestHeader;
public abstract class BaseController { protected final TokenService tokens; protected final UserRepository users; protected BaseController(TokenService t,UserRepository u){tokens=t;users=u;} protected Long currentId(@RequestHeader("Authorization") String h){String token=h==null?"":h.replaceFirst("^Bearer\\s*","");Long id=tokens.user(token);if(id==null)throw new RuntimeException("Your session has expired. Please sign in again.");return id;} protected User currentUser(String h){return users.findById(currentId(h)).orElseThrow(()->new RuntimeException("User account was not found."));} }
